// P.I.G. desktop robot arm: NUCLEO-F401RE + PCA9685 (Adafruit #815) driving
// 3x MG995 (base, shoulder, elbow) and 3x MG90S (wrist pitch, wrist roll, gripper).
// Pick-and-place loop with per-joint limits and an E-stop that pulls the
// PCA9685 /OE line high (all outputs off) and stops motion.
#include <SPI.h>  // Adafruit BusIO (pulled in by the driver) includes SPI.h
#include <Wire.h>
#include <Adafruit_PWMServoDriver.h>

static const uint8_t PCA_ADDR = 0x40;
static const uint8_t PIN_OE = D7;     // PA8 -> PCA9685 /OE (high = outputs disabled)
static const uint8_t PIN_ESTOP = D2;  // PA10 <- E-stop contact to GND, pull-up

Adafruit_PWMServoDriver pwm(PCA_ADDR, Wire);

// 50 Hz frame, 4096 counts per 20 ms: 500 us = 102 counts, 2500 us = 512 counts.
static const uint16_t PULSE_MIN = 102;
static const uint16_t PULSE_MAX = 512;

struct Joint {
  const char *name;
  uint8_t channel;
  int16_t minDeg;
  int16_t maxDeg;
  int16_t deg;
};

// Channel order = PCA9685 LED0..LED5.
Joint joints[6] = {
  {"base", 0, 10, 170, 90},
  {"shoulder", 1, 30, 150, 90},
  {"elbow", 2, 20, 160, 90},
  {"wrist_pitch", 3, 20, 160, 90},
  {"wrist_roll", 4, 0, 180, 90},
  {"gripper", 5, 30, 110, 40},
};

struct Pose {
  const char *name;
  int16_t deg[6];
};

static const Pose poses[] = {
  {"home", {90, 90, 90, 90, 90, 40}},
  {"over_pick", {45, 70, 120, 60, 90, 40}},
  {"pick_down", {45, 55, 135, 50, 90, 40}},
  {"grip", {45, 55, 135, 50, 90, 105}},
  {"lift", {45, 80, 110, 70, 90, 105}},
  {"over_place", {135, 80, 110, 70, 120, 105}},
  {"place_down", {135, 58, 132, 52, 120, 105}},
  {"release", {135, 58, 132, 52, 120, 40}},
  {"home", {90, 90, 90, 90, 90, 40}},
};

static bool estopped = false;

static uint16_t degToCounts(int16_t deg) {
  return PULSE_MIN + (uint32_t)(PULSE_MAX - PULSE_MIN) * (uint32_t)deg / 180u;
}

static int16_t clampJoint(const Joint &j, int16_t deg) {
  if (deg < j.minDeg) return j.minDeg;
  if (deg > j.maxDeg) return j.maxDeg;
  return deg;
}

static bool readReg(uint8_t reg, uint8_t *out, uint8_t n) {
  Wire.beginTransmission(PCA_ADDR);
  Wire.write(reg);
  if (Wire.endTransmission(false) != 0) return false;
  if (Wire.requestFrom(PCA_ADDR, n) != n) return false;
  for (uint8_t i = 0; i < n; i++) out[i] = Wire.read();
  return true;
}

static int32_t readOffCounts(uint8_t ch) {
  uint8_t b[2];
  if (!readReg(0x08 + 4 * ch, b, 2)) return -1;  // LEDn_OFF_L, LEDn_OFF_H
  return (int32_t)b[0] | ((int32_t)(b[1] & 0x0F) << 8);
}

static void enterEstop() {
  digitalWrite(PIN_OE, HIGH);  // hardware disable of every PCA9685 output
  estopped = true;
  Serial.println("ESTOP OE=1 motion=stopped");
}

static bool checkEstop() {
  if (!estopped && digitalRead(PIN_ESTOP) == LOW) enterEstop();
  return estopped;
}

static void writeJoint(Joint &j, int16_t deg) {
  j.deg = clampJoint(j, deg);
  pwm.setPWM(j.channel, 0, degToCounts(j.deg));
}

// Move all joints together in 5 degree increments, checking the E-stop each step.
static bool moveTo(const Pose &p) {
  bool moving = true;
  while (moving) {
    if (checkEstop()) return false;
    moving = false;
    for (uint8_t i = 0; i < 6; i++) {
      int16_t target = clampJoint(joints[i], p.deg[i]);
      int16_t d = target - joints[i].deg;
      if (d == 0) continue;
      moving = true;
      if (d > 5) d = 5;
      if (d < -5) d = -5;
      writeJoint(joints[i], joints[i].deg + d);
    }
    delay(2);
  }
  return true;
}

static void reportPose(uint8_t step, const Pose &p) {
  Serial.print("POSE ");
  Serial.print(step);
  Serial.print(' ');
  Serial.println(p.name);
  bool ok = true;
  for (uint8_t i = 0; i < 6; i++) {
    const Joint &j = joints[i];
    int32_t off = readOffCounts(j.channel);
    Serial.print("  J");
    Serial.print(j.channel);
    Serial.print(' ');
    Serial.print(j.name);
    Serial.print(" deg=");
    Serial.print(j.deg);
    Serial.print(" off=");
    Serial.println(off);
    if (off < degToCounts(j.minDeg) || off > degToCounts(j.maxDeg)) ok = false;
  }
  Serial.println(ok ? "LIMITS_OK" : "LIMIT_VIOLATION");
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN_OE, OUTPUT);
  digitalWrite(PIN_OE, HIGH);  // outputs off until every servo has a valid pulse
  pinMode(PIN_ESTOP, INPUT_PULLUP);
  Wire.setSDA(PB9);  // Arduino header D14/D15 on the Nucleo
  Wire.setSCL(PB8);
  Wire.begin();
  Serial.println("PIG BOOT");

  Wire.beginTransmission(PCA_ADDR);
  if (Wire.endTransmission() != 0) {
    Serial.println("PCA9685_MISSING");
    estopped = true;
    return;
  }
  pwm.begin();
  pwm.setPWMFreq(50);
  uint8_t prescale = 0;
  readReg(0xFE, &prescale, 1);
  Serial.print("PCA9685_OK addr=0x40 prescale=");
  Serial.println(prescale);
  for (uint8_t i = 0; i < 6; i++) writeJoint(joints[i], joints[i].deg);
  digitalWrite(PIN_OE, LOW);  // enable outputs
  Serial.println("OE=0 armed");
}

static uint8_t cycle = 0;

void loop() {
  if (estopped) {
    delay(10);
    return;
  }
  cycle++;
  Serial.print("CYCLE ");
  Serial.println(cycle);
  for (uint8_t s = 0; s < sizeof(poses) / sizeof(poses[0]); s++) {
    if (!moveTo(poses[s])) {
      Serial.println("HALTED");
      return;
    }
    reportPose(s, poses[s]);
  }
  Serial.println("SEQ_DONE");
}
